insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800211', '40000000-0000-4000-8000-000000080021', 'A', '$2x+1$', 1), ('50000000-0000-4000-8000-000000800212', '40000000-0000-4000-8000-000000080021', 'B', '$x+1$', 2), ('50000000-0000-4000-8000-000000800213', '40000000-0000-4000-8000-000000080021', 'C', '$2x$', 3), ('50000000-0000-4000-8000-000000800214', '40000000-0000-4000-8000-000000080021', 'D', '$x^2+1$', 4)
