insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800311', '40000000-0000-4000-8000-000000080031', 'A', '$2$', 1), ('50000000-0000-4000-8000-000000800312', '40000000-0000-4000-8000-000000080031', 'B', '$1$', 2), ('50000000-0000-4000-8000-000000800313', '40000000-0000-4000-8000-000000080031', 'C', '$-2$', 3), ('50000000-0000-4000-8000-000000800314', '40000000-0000-4000-8000-000000080031', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000080031', '50000000-0000-4000-8000-000000800311') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000080031', '30000000-0000-4000-8000-000000000029', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800311', '40000000-0000-4000-8000-000000080031', 'A parábola está na forma de vértice.', 1), ('60000000-0000-4000-8000-000000800312', '40000000-0000-4000-8000-000000080031', 'O coeficiente negativo indica abertura para baixo.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080031', '$x=2$.', 'Uma parábola com sinal negativo abre para baixo, então seu vértice representa o maior valor possível. A forma quadrada mostra diretamente a posição horizontal do vértice: o quadrado é mínimo quando vale zero. Assim, maximizar a função equivale a escolher o valor de x que anula o termo entre parênteses.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
