insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080039', '$x=10$.', 'Uma parábola com sinal negativo abre para baixo, então seu vértice representa o maior valor possível. A forma quadrada mostra diretamente a posição horizontal do vértice: o quadrado é mínimo quando vale zero. Assim, maximizar a função equivale a escolher o valor de x que anula o termo entre parênteses.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800391', '40000000-0000-4000-8000-000000080039', 'Observe a estrutura', '$f(x)=-(x-10)^2+9$', 1), ('70000000-0000-4000-8000-000000800392', '40000000-0000-4000-8000-000000080039', 'Escolha a regra', 'O quadrado é sempre não negativo.', 2), ('70000000-0000-4000-8000-000000800393', '40000000-0000-4000-8000-000000080039', 'Calcule', '$(x-10)^2=0$', 3), ('70000000-0000-4000-8000-000000800394', '40000000-0000-4000-8000-000000080039', 'Interprete', '$x=10$', 4), ('70000000-0000-4000-8000-000000800395', '40000000-0000-4000-8000-000000080039', 'Confira', 'Com sinal negativo, afastar-se do vértice só diminui a função.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000080040', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000010', 'multiple_choice', 'hard', 'published', 'Em qual valor de $x$ a função $f(x)=-(x-11)^2+10$ atinge seu máximo?')
